import 'package:flutter/foundation.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'models.dart';
class CareStore extends ChangeNotifier { CareStore._(); static Future<CareStore> create() async { final s=CareStore._(); s.p=await SharedPreferences.getInstance(); s.med=s.p.getBool('med')==true?MedicationStatus.completed:MedicationStatus.pending; return s; } late SharedPreferences p; Role activeRole=Role.caregiver; MedicationStatus med=MedicationStatus.pending; bool help=false; final members=const [FamilyMember(id:'mother',name:'Mother',role:Role.mother,status:'At home'),FamilyMember(id:'father',name:'Father',role:Role.father,status:'Appointment tomorrow'),FamilyMember(id:'child',name:'Child',role:Role.child,status:'Homework needs help')]; final tasks=<Task>[const Task(id:'homework',title:'Finish maths homework',assigneeId:'child',needsHelp:true),const Task(id:'appointment',title:'Help Father get to annual checkup',assigneeId:'caregiver')]; List<Alert> get alerts=>[if(med==MedicationStatus.pending)const Alert(title:'Mother medication is pending',detail:'Please complete today medication check-in.',highPriority:true),const Alert(title:'Father appointment',detail:'Tomorrow — assign related task if needed.',highPriority:false),if(help)const Alert(title:'Assistance requested',detail:'A family member needs support.',highPriority:true),if(tasks.any((t)=>t.needsHelp&&!t.complete))const Alert(title:'Child needs help with homework',detail:'A normal family attention item.',highPriority:false)]; void setRole(Role r){activeRole=r;notifyListeners();} Future<void> completeMedication() async {med=MedicationStatus.completed;await p.setBool('med',true);notifyListeners();} void checkIn(CheckInType t){if(t==CheckInType.medicationCompleted){completeMedication();return;}help=t==CheckInType.needAssistance;notifyListeners();} void updateTask(Task t){final i=tasks.indexWhere((x)=>x.id==t.id);tasks[i]=t;notifyListeners();} }
